  l('r:李雄@chenghan', '叔', 'r:李班@chenghan', '人核：《晉書》卷121：「其後將立蕩子班為太子」（同卷「琀、稚，雄兄蕩之子也」）', 1, '李班是李雄长兄李荡之子，李雄以侄为太子；生父李荡（李特次子）');
  l('r:李班@chenghan', '从兄弟', 'r:李期@chenghan', '人核：《晉書》卷121：「期字世運，雄第四子也」', 1, '李期是李雄第四子，李班是李雄兄李荡之子，二人同为李特之孙；李期生父李雄');
  l('r:刘渊@hanzhao', '父', 'r:刘和@hanzhao', '人核：《晉書》卷101：「元海死，和嗣偽位」（卷首注「劉元海（子和）」）', 1, '刘和是刘渊之子，刘渊死后嗣位七日为刘聪所杀；生父刘渊');
  l('r:刘和@hanzhao', '兄弟', 'r:刘聪@hanzhao', '人核：《晉書》卷102：「劉聰，字玄明，一名載，元海第四子也」', 1, '刘聪是刘渊第四子，与刘和同为刘渊之子；生父刘渊');
  l('r:石弘@houzhao', '从兄弟', 'r:石虎@houzhao', '人核：《晉書》卷106：「石季龍，勒之從子也」；卷105：「弘字大雅，勒之第二子也」', 1, '石虎是石勒之从子（侄），石弘是石勒第二子，二人同以石勒之父周曷朱为祖；石虎生父石寇觅');
  l('r:赫连昌@xia', '兄弟', 'r:赫连定@xia', '人核：《晉書》卷130：「子昌嗣偽位，尋為魏所擒。弟定僭號於平涼」', 1, '赫连定是赫连昌之弟，同为赫连勃勃之子；生父赫连勃勃');
  l('r:张寔@qianliang', '兄弟', 'r:张茂@qianliang', '人核：《晉書》卷086：「祖寔為昭王，從祖茂為成王」（张祚追崇诏；卷目作「寔弟茂」）', 1, '张茂是张寔之弟，同为张轨之子；生父张轨');
  l('r:张茂@qianliang', '叔', 'r:张骏@qianliang', '人核：《晉書》卷086：「從祖茂為成王，父駿為文王」（张祚追崇诏；卷目作「茂兄子駿」）', 1, '张骏是张寔之子、张茂之侄，叔死侄立；生父张寔');
  l('r:张天锡@qianliang', '叔', 'r:张玄靓@qianliang', '人核：《晉書》卷086：「天錫字純嘏，駿少子也」「玄靚乃以邕為中護軍，叔父天錫為中領軍」', 1, '张天锡是张骏少子、张玄靓之叔父，弑侄自立；张玄靓生父张重华（张骏第二子）');
  l('r:刘义隆@song_l', '父', 'r:刘劭@song_l', '人核：《宋書》卷99：「元凶劭字休遠，文帝長子也」', 1, '刘劭是宋文帝长子，弑父自立；生父刘义隆');
  l('r:刘劭@song_l', '兄弟', 'r:刘骏@song_l', '人核：《宋書》卷6：「世祖孝武皇帝諱駿，字休龍，小字道民，文帝第三子也」', 1, '刘骏是宋文帝第三子，与刘劭同为文帝之子，起兵讨杀其兄；生父刘义隆');
  l('r:陈蒨@chen', '父', 'r:陈伯宗@chen', '人核：《陳書》卷4：「廢帝諱伯宗，字奉業，小字藥王，世祖嫡長子也」', 1, '陈伯宗是陈文帝嫡长子；生父陈蒨');
  l('r:陈顼@chen', '叔', 'r:陈伯宗@chen', '人核：《陳書》卷5：「高宗孝宣皇帝諱頊……始興昭烈王第二子也」；卷3：「世祖文皇帝諱蒨……始興昭烈王長子也」', 1, '陈顼是始兴昭烈王陈道谈第二子、陈文帝之弟，即陈伯宗之叔父，废侄自立；生父陈道谈');
  l('r:郭威@hzhou', '养父', 'r:柴荣@hzhou', '人核：《舊五代史》卷114：「世宗睿武孝文皇帝，諱榮，太祖之養子，蓋聖穆皇后之侄也。本姓柴氏，父守禮」', 1, '柴荣本姓柴，是郭威妻圣穆皇后之侄，郭威无子而养为己子；生父柴守礼');
  l('r:刘崇@bhan', '父', 'r:刘承钧@bhan', '人核：《新五代史》卷70：「（劉旻）以子承鈞為太原尹」（卷目作「劉旻（子承鈞）」）', 1, '刘承钧是刘崇（旻）之子；生父刘崇');
  l('r:段思良@dali', '叔', 'r:段思英@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「是年，帝叔思良爭位，廢帝為僧」（节题「聖慈文武皇帝　太祖之弟」）', 2, '段思良是太祖段思平之弟、段思英之叔父，废侄自立；段思良生父段保隆，段思英生父段思平');
  l('r:段素顺@dali', '父', 'r:段素英@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「素順卒，在位十六年，子素英立」', 2, '段素英是段素顺之子；生父段素顺');
  l('r:段素英@dali', '父', 'r:段素廉@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「素英卒，在位二十四年，子素廉立」', 2, '段素廉是段素英之子；生父段素英');
  l('r:段素廉@dali', '叔', 'r:段素隆@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「素廉卒，在位十三年。姪素隆立」', 2, '段素隆是段素廉之侄、段素英之孙，叔死侄立；生父为段素廉之兄弟（史失其名）');
  l('r:段素隆@dali', '叔', 'r:段素真@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「素隆禪位為僧，在位四年。姪素真立」', 2, '段素真是段素隆之侄，段素隆禅位为僧而侄立；生父先卒（史失其名）');
  l('r:段素真@dali', '祖', 'r:段素兴@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「素真禪位為僧，在位十五年，孫素興立」', 2, '段素兴是段素真之孙，其父先亡故以孙继；祖父段素真');
  l('r:段思廉@dali', '父', 'r:段廉义@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「思廉禪位為僧，在位三十一年，子廉義立」', 2, '段廉义是段思廉之子；生父段思廉');
  l('r:段廉义@dali', '叔', 'r:段寿辉@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「討而誅之，立廉義之姪壽輝」', 2, '段寿辉是段廉义之侄（段思廉之孙），杨义贞弑段廉义后为高氏所立；生父为段廉义之兄弟（史失其名）');
  l('r:段寿辉@dali', '从兄弟', 'r:段正明@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「壽輝因天變，遂禪位於思廉之孫正明」（节题「正明　思廉之孫」）', 2, '段寿辉与段正明同为段思廉之孙而父不同（寿辉系段廉义之侄，正明系段廉义一系），故为从兄弟');
  l('r:段正明@dali', '兄弟', 'r:段正淳@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「其子高泰明遵遺命，還位正明之弟正湻」（节题「段正湻　大理國正明之弟」）', 2, '段正淳是段正明之弟，高升泰临终还政于段氏立之；二人同为段思廉之孙');
  l('r:段智廉@dali', '兄弟', 'r:段智祥@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「智廉卒，在位五年。弟智祥立」', 2, '段智祥是段智廉之弟，同为段智兴之子；生父段智兴');
  l('r:段智祥@dali', '父', 'r:段祥兴@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「智祥禪位為僧，在位三十三年。子祥興立」', 2, '段祥兴是段智祥之子；生父段智祥');
  l('r:段祥兴@dali', '父', 'r:段兴智@dali', '人核：《南詔野史》（胡蔚本，明倪辂辑清胡蔚订，非正史）：「祥興卒，在位十三年。子興智立」', 2, '段兴智是段祥兴之子，大理末主；生父段祥兴');
